export const SAMPLE_TEXT='PROJECT NOTES\n\nA clearer archive\n\nCapture important pages, review the words, and keep the result in one place.\n\nProject: Paper Study\nDate: 14 October 2026\n\nThe original scan remains available. A searchable PDF keeps its appearance; regenerated text creates a clean reading layout.';
const base={version:1,mode:'document',workflow:'paired',captures:[{id:'sample-1',label:'Page 1',kind:'document',side:'Single',rotation:0,filter:'Color',brightness:100,contrast:100,corners:[[8,6],[92,6],[92,94],[8,94]],text:SAMPLE_TEXT}],active:0,title:'Project notes',output:'searchable',paper:'A4',template:'Stacked',margins:'Comfortable',brightness:100,contrast:100,ocrReady:false,pairConfirmed:false,draft:false,draftSnapshot:null,currentId:null,exportReady:false,exportData:null,library:[{id:'notes',title:'Project notes',type:'document',pages:2,output:'searchable',date:'Today',text:SAMPLE_TEXT},{id:'cards',title:'Studio card set',type:'cards',pages:1,output:'searchable',date:'Yesterday',text:'Studio membership. Sample card.'}],settings:{paper:'A4',quality:'High',lab:true},query:'',introDone:false};
export function fresh(){return structuredClone(base)}
function cleanRegions(regions){return regions.filter(r=>r&&typeof r==='object').map((r,i)=>({...structuredClone(base.captures[0]),...r,id:String(r.id??`restored-${i}`),label:String(r.label??`Page ${i+1}`),kind:r.kind==='card'?'card':'document',side:['Front','Back','Single'].includes(r.side)?r.side:'Single',text:typeof r.text==='string'?r.text:SAMPLE_TEXT,filter:['Original','Color','Grayscale','B&W'].includes(r.filter)?r.filter:'Color',brightness:Number.isFinite(r.brightness)?Math.max(75,Math.min(125,r.brightness)):100,contrast:Number.isFinite(r.contrast)?Math.max(75,Math.min(140,r.contrast)):100,corners:Array.isArray(r.corners)&&r.corners.length===4&&r.corners.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))?r.corners:structuredClone(base.captures[0].corners)}));}
export function load(){try{const v=JSON.parse(localStorage.getItem('ocr-design-v1'));if(v?.version!==1||!Array.isArray(v.captures)||!Array.isArray(v.library))return fresh();const s={...fresh(),...v,captures:cleanRegions(v.captures),library:v.library.filter(d=>d&&typeof d.id==='string'&&typeof d.title==='string').map(d=>({...d,type:d.type==='cards'?'cards':'document',pages:Math.max(1,Number(d.pages)||1),text:typeof d.text==='string'?d.text:'',captures:Array.isArray(d.captures)?cleanRegions(d.captures):undefined})),settings:{...base.settings,...v.settings}};s.title=typeof s.title==='string'?s.title:'Untitled scan';s.query=typeof s.query==='string'?s.query:'';s.active=Math.max(0,Math.min(s.captures.length-1,Number.isInteger(s.active)?s.active:0));s.mode=s.mode==='cards'?'cards':'document';s.workflow=s.workflow==='multiple'?'multiple':'paired';s.output=s.output==='text'?'text':'searchable';s.paper=['A4','Letter','Auto'].includes(s.paper)?s.paper:'A4';s.template=['Stacked','Side by side','Grid'].includes(s.template)?s.template:'Stacked';s.margins=s.margins==='Compact'?'Compact':'Comfortable';s.settings.paper=['A4','Letter'].includes(s.settings.paper)?s.settings.paper:'A4';s.settings.quality=s.settings.quality==='Standard'?'Standard':'High';s.settings.lab=s.settings.lab!==false;if(s.draftSnapshot){if(!Array.isArray(s.draftSnapshot.captures))s.draftSnapshot=null;else s.draftSnapshot.captures=cleanRegions(s.draftSnapshot.captures)}return s;}catch{}return fresh()}
export const state=load();
export let storageAvailable=true;
export const draftKeys=['mode','workflow','captures','active','title','output','paper','template','margins','brightness','contrast','ocrReady','pairConfirmed','exportReady','exportData','currentId'];
export function save(){if(state.draft)state.draftSnapshot=Object.fromEntries(draftKeys.map(k=>[k,structuredClone(state[k])]));try{localStorage.setItem('ocr-design-v1',JSON.stringify(state));storageAvailable=true;return true;}catch{storageAvailable=false;return false;}}
let sequence=0;
export function makeRegion(kind='document',side='Single'){return {id:`region-${Date.now()}-${++sequence}`,label:kind==='card'?`Card ${state.captures.length+1}`:`Page ${state.captures.length+1}`,kind,side,rotation:0,filter:'Color',brightness:100,contrast:100,corners:[[8,6],[92,6],[92,94],[8,94]],text:kind==='card'?'STUDIO MEMBERSHIP\nSample member\nDesign study only':SAMPLE_TEXT};}
export function active(){return state.captures[state.active]??state.captures[0]}
export function startDraft(add=false){if(!add){state.captures=[];state.active=0;state.title='Untitled scan';state.mode='document';state.workflow='paired';state.template='Stacked';state.margins='Comfortable';state.output='searchable';state.brightness=100;state.contrast=100;state.pairConfirmed=false;state.ocrReady=false;state.exportReady=false;state.exportData=null;state.currentId=null;}state.draft=true;state.paper=state.settings.paper;save();}
export function invalidateExport(){state.exportReady=false;state.exportData=null;state.draft=true;save()}
export function invalidate(){state.ocrReady=false;state.exportReady=false;state.exportData=null;state.draft=true;save()}
export function ensureSample(){if(!state.captures.length){state.captures=[makeRegion(state.mode==='cards'?'card':'document',state.mode==='cards'?'Front':'Single')];state.active=0;save()}}
